using System; using System.Drawing; using System.Linq; using System.Windows.Forms; using Entidades; using Negocio;
namespace Presentacion { public class FormHistorialVentas:Form { VentaNegocio negocio=new VentaNegocio(); DataGridView dgv=new DataGridView(); TextBox txtCliente=new TextBox(); DateTimePicker fecha=new DateTimePicker();
 public FormHistorialVentas(){Text="Historial de ventas - Mystic Charm";Size=new Size(900,520);StartPosition=FormStartPosition.CenterParent;BackColor=Color.FromArgb(250,245,239);Controls.Add(new Label{Text="Historial de ventas",Font=new Font("Georgia",20),AutoSize=true,Location=new Point(20,15)});Controls.Add(new Label{Text="Cliente",AutoSize=true,Location=new Point(20,65)});txtCliente.SetBounds(75,62,180,25);Controls.Add(txtCliente);var bc=new Button{Text="Buscar cliente",Location=new Point(265,60),Size=new Size(110,28)};bc.Click+=(s,e)=>Cargar(negocio.BuscarPorCliente(txtCliente.Text));Controls.Add(bc);fecha.SetBounds(400,62,130,25);fecha.Format=DateTimePickerFormat.Short;Controls.Add(fecha);var bf=new Button{Text="Buscar fecha",Location=new Point(540,60),Size=new Size(100,28)};bf.Click+=(s,e)=>Cargar(negocio.BuscarPorFecha(fecha.Value));Controls.Add(bf);var bt=new Button{Text="Ver todas",Location=new Point(650,60),Size=new Size(90,28)};bt.Click+=(s,e)=>Cargar(negocio.ListarVentas());Controls.Add(bt);
 dgv.SetBounds(20,105,840,280);dgv.ReadOnly=true;dgv.SelectionMode=DataGridViewSelectionMode.FullRowSelect;dgv.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;Controls.Add(dgv);var bd=new Button{Text="Ver detalle",Location=new Point(20,405),Size=new Size(110,32)};bd.Click+=Detalle;Controls.Add(bd);var bx=new Button{Text="Cancelar venta",Location=new Point(140,405),Size=new Size(120,32)};bx.Click+=Cancelar;Controls.Add(bx);Cargar(negocio.ListarVentas());}
 void Cargar(System.Collections.Generic.List<Venta> vs){dgv.DataSource=null;dgv.DataSource=vs.Select(v=>new{v.IdVenta,Fecha=v.Fecha,Cliente=v.Cliente==null?"":v.Cliente.Nombre+" "+v.Cliente.Apellido,v.Total}).ToList();}
 Venta Seleccionada(){if(dgv.CurrentRow==null)return null;int id=(int)dgv.CurrentRow.Cells["IdVenta"].Value;return negocio.ListarVentas().Find(v=>v.IdVenta==id);} void Detalle(object s,EventArgs e){var v=Seleccionada();if(v==null)return;string t=string.Join(Environment.NewLine,v.Detalles.Select(d=>d.Producto.Nombre+" x"+d.Cantidad+" - $"+d.Subtotal.ToString("N0")));MessageBox.Show(t+Environment.NewLine+"Total: $"+v.Total.ToString("N0"),"Detalle venta N° "+v.IdVenta);}
 void Cancelar(object s,EventArgs e){var v=Seleccionada();if(v==null)return;if(MessageBox.Show("¿Cancelar la venta y devolver el stock?","Confirmar",MessageBoxButtons.YesNo)==DialogResult.Yes){negocio.CancelarVenta(v);Cargar(negocio.ListarVentas());}}
}}
